}

// ---- tiny preload helper (prevents blank/partial renders) ----
function preloadHTML(urls){
  const uniq = Array.from(new Set((urls || []).filter(u => typeof u === 'string' && u)));
  if (!uniq.length) return '';
  const imgs = uniq.map(u => `<img src="${u}" width="1" height="1" alt="" loading="eager" decoding="sync">`).join('');
  return `<div class="__preloads" style="position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden;opacity:0;visibility:hidden;">${imgs}</div>`;
}

// ---- background/overlay layer emitters (CSS bg vs <img> toggle) ----
function bgLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-bg" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-bg"><img src="${url}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}
function overlayLayerHTML(url){
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-overlay" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-overlay"><img src="${url}" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}

// ---- text helpers ----
function prettifyText(raw){
  const withBr = String(raw || '').replace(/\n/g, '<br>');
  const parts = withBr.split('<br>');
  const widont = (seg) => seg.replace(/\s+([^\s<]{1,12})\s*$/u, '&nbsp;$1');
  return parts.map(s => widont(s.trim())).join('<br>');
}
function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, (m) => (
    {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[m]
  ));
}

