const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const http = this.helpers.httpRequest;
const AUTH_HEADER = { Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR' };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;

async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 30) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method: 'GET', url: apiBase + docId, json: true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++;
  await sleep(1800 + Math.floor(Math.random()*600));
}

