const isFullDoc = /<\s*!doctype/i.test(html) || /<\s*html[\s>]/i.test(html);
function injectCss(docHtml, cssText){
  const styleTag = `<style id="cover-css">${cssText}</style>`;
  if (/<\s*head[\s>]/i.test(docHtml)) {
    return docHtml.replace(/<\/\s*head\s*>/i, `${styleTag}\n</head>`);
  }
  return docHtml.replace(/<\s*html[^>]*>/i, (m)=>`${m}\n<head>${styleTag}</head>`);
}

if (!isFullDoc) {
  html = `<!doctype html><html><head><meta charset="utf-8"><style>${COVER_CSS}</style></head><body>${html}</body></html>`;
} else {
  html = injectCss(html, COVER_CSS);
}

// Emit as JSON + Binary
const data = Buffer.from(html, 'utf8').toString('base64');
return [{
  json: { ...j, cover_preview_html: html, cover_preview_filename: 'cover-preview.html' },
  binary: { data: { data, fileName: 'cover-preview.html', mimeType: 'text/html' } }
}];

// Build Standalone Interior Preview HTML (2625px) — PDFMonkey-parity preview + debug

// 0) PDFMONKEY CSS (modified per your specs)
const PDFMONKEY_TEMPLATE_CSS = `
/* ==== IMAGE TEMPLATE CSS — 2625×2625px canvas (all px units) ==== */

/* Font */
@font-face{
  font-family:'CustomBook';
  src:
    url('https://admin.littleherolabs.com/api/assets/book-mvp-simple-adventure/fonts/custom-font.woff2') format('woff2'),
    url('https://admin.littleherolabs.com/api/assets/book-mvp-simple-adventure/fonts/custom-font.ttf') format('truetype');
  font-display: swap;
}

:root{
  --book-font:'CustomBook', Arial, sans-serif;
  --overlay-tint: rgba(255,255,255,0.20);
}

/* Fixed canvas */
html, body { margin:0; padding:0; width:2625px; height:2625px; overflow:hidden; }
* { box-sizing:border-box; }

/* One page */
.book-page{
  position:relative;
  width:2625px; height:2625px;
  overflow:hidden;
  display:block;
}

/* Full-bleed background */
.page-bg{
  position:absolute; inset:0;
  background:no-repeat center / cover;
  z-index:0;
}

/* Optional page overlay */
.page-overlay{
  position:absolute; inset:0;
  background:no-repeat center / cover;
  z-index:1;
}

/* Text box — 20% larger (W & H), rounded, clipped, full overlay visible */
.text-box{
  position:absolute; left:50%; bottom:3%;
  width:96%;                        /* was 80% → +20% width */
  transform:translateX(-50%);

  background-image: var(--overlay-url);
  background-repeat:no-repeat;
  background-position:center center;
  background-size:contain;          /* show full overlay art */

  padding:24px 300px;               /* was 20px 250px → +20% */
  min-height:360px;                 /* was 300px → +20% */

  display:flex; align-items:center; justify-content:center;
  z-index:5;
  border-radius:12px;
  background-color:transparent;
  background-clip:padding-box;
  overflow:hidden;
}

.text-content{
  font-family:var(--book-font);
  font-size:50px;
  line-height:1.35;
  letter-spacing:1px;
  color:#312116;
  text-align:center;
  text-wrap:balance; hyphens:auto; overflow-wrap:break-word; word-break:normal;
  widows:2; orphans:2;
