  -webkit-font-smoothing:antialiased;
}

/* Sprites */
.character, .animal { position:absolute; }
.character img, .animal img { width:100%; height:auto; display:block; }
`.trim();

// 1) Pull data from current input or upstream
let src = $input.first()?.json || {};
let pagesArr = Array.isArray(src.interiorPagesHTML) ? src.interiorPagesHTML.slice() : [];
let pagesHtml = String(src.pages_html || '');

// Try upstream nodes if needed
function pickFromNode(name){
  try {
    const it = $items(name, 0, $runIndex);
    if (!Array.isArray(it) || !it.length) return;
    const j = it[0]?.json || {};
    if (!pagesArr.length && Array.isArray(j.interiorPagesHTML)) pagesArr = j.interiorPagesHTML.slice();
    if (!pagesHtml && j.pages_html) pagesHtml = String(j.pages_html);
  } catch {}
}
[
  'Generate Complete HTML (Interior pages) — Phase 2',
  'Generate Complete HTML (Interior pages) - Phase 2',
  'Generate Complete HTML (Interior pages)',
].forEach(pickFromNode);

// Last-resort: split big HTML string into page blocks
if (!pagesArr.length && pagesHtml) {
  pagesArr = pagesHtml
    .split(/(?=<div\s+class=["']book-page["'][^>]*>)/i)
    .filter(Boolean);
}

// Bail if still nothing
if (!pagesArr.length) {
  throw new Error('Preview: no pages found (interiorPagesHTML/pages_html empty).');
}

// 2) PREVIEW CHROME (debug badges)
const PX = 2625;
const previewCss = `
  html, body { width:auto !important; height:auto !important; overflow:auto !important; background:#131313 !important; }
  .stack { width:100%; max-width:${PX + 128}px; margin:24px auto 72px; display:flex; flex-direction:column; gap:24px; align-items:center; }
  .page-wrap { position:relative; box-shadow:0 10px 30px rgba(0,0,0,.45); border-radius:8px; overflow:hidden; background:#000; }
  .page-wrap .book-page { width:${PX}px !important; height:${PX}px !important; display:block !important; }
  .page-wrap::after { content:""; position:absolute; inset:0; outline:1px dashed rgba(255,255,255,.25); pointer-events:none; border-radius:8px; }
  .page-label { position:absolute; left:10px; top:8px; font:12px/1.2 system-ui,-apple-system,Segoe UI,Roboto,Arial; color:#fff; text-shadow:0 1px 2px #000; background:rgba(0,0,0,.35); padding:4px 6px; border-radius:4px; }
  .page-wrap.warn { outline:3px solid #ef4444; }
`.trim();

const outerChromeCss = `*{box-sizing:border-box;}`;

// Wrap each page with debug flags
const wrapped = pagesArr
  .map((p, idx) => {
    const hasChar    = /class=["']character\b/i.test(p);
    const hasAnimal  = /class=["']animal\b/i.test(p);
    const hasOverlay = /class=["']page-overlay\b/i.test(p);
    const hasTextBox = /class=["']text-box\b/i.test(p);
    const hasTextContent = /class=["']text-content\b/i.test(p);
    const flags = [
      hasChar ? 'char✔' : 'char✖',
      hasAnimal ? 'animal✔' : 'animal✖',
      hasOverlay ? 'overlay✔' : 'overlay✖',
      hasTextBox ? 'textbox✔' : 'textbox✖',
      hasTextContent ? 'text-content✔' : 'text-content✖'
    ].join(' · ');
    const warn = (!hasChar) || (idx===13 && !hasAnimal) || ((idx===5 || idx===12) && !hasOverlay) || (idx===5 && !hasTextContent);
    return `<div class="page-wrap${warn ? ' warn' : ''}">
      ${p}
      <div class="page-label">Page ${idx} — ${flags}</div>
    </div>`;
  })
  .join('\n');

// 3) Build HTML
const html = `
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>Interior Preview — ${src.characterSpecs?.childName || 'Book'}</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>${outerChromeCss}</style>
  <style>${PDFMONKEY_TEMPLATE_CSS}</style>
  <style>${previewCss}</style>
</head>
<body>
  <div class="stack">
    ${wrapped}
  </div>
</body>
</html>
`.trim();

// Return as JSON + Binary for download
const data = Buffer.from(html, 'utf8').toString('base64');
return [{
  json: {
    ...src,
    preview_html: html,
    preview_filename: 'interior-preview.html',
  },
  binary: {
    data: {
      data,
      fileName: 'interior-preview.html',
      mimeType: 'text/html',
    }
  }
}];
